// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // fuzz a caller address to ensure owner() always reports the stored owner (deployer) regardless of who calls
    function testFuzz_property(address caller) public {
        // keep domain wide but avoid zero address since owner can be zero in some flows; here after construction owner should be non-zero
        vm.assume(caller != address(0));

        // call owner() from arbitrary caller context
        bool ok;
        address reported;
        // use try/catch to capture potential reverts (spec requirement)
        try c.owner() returns (address o) {
            ok = true;
            reported = o;
        } catch {
            ok = false;
            reported = address(0);
        }

        // The reference contract constructed in setUp sets owner to deployer (this contract). So owner() must succeed and equal address(this).
        // Single assertion: owner() call succeeded and returned the deployer address.
        assertTrue(ok && reported == address(this));
    }
}

