    C c;
    function setUp() public { c = new C(address(this)); }

    // fuzzed caller address: the fuzzer will supply arbitrary addresses
    function testFuzz_property(address caller) public {
        // Keep domain wide but avoid the zero address for caller because vm.prank with address(0) is ambiguous
        // We still allow caller == address(0) to be fuzzed; handle it by using a fallback valid caller when zero.
        address effectiveCaller = caller;
        if (effectiveCaller == address(0)) {
            effectiveCaller = address(0xBEEF);
        }

        // call owner() from the fuzzed caller context to observe returned value
        bool ok;
        address returned;
        vm.prank(effectiveCaller);
        try c.owner() returns (address r) {
            ok = true;
            returned = r;
        } catch {
            ok = false;
            returned = address(0);
        }

        // General property: reference returns a non-zero owner (the deployer) and call succeeds for any caller.
        // We assert that the call succeeded and returned a non-zero address.
        assertTrue(ok && returned != address(0));
    }
}

