pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // fuzzed parameter: any caller address. The universal rule we assert:
    // for any address caller, calling c.owner() should succeed and return the deployer (non-zero) in the reference;
    // the mutant returns address(0) breaking this. We make the fuzzer pick the caller.
    function testFuzz_property(address caller) public {
        // keep domain wide but non-zero to avoid trivial zero-address pruning if desired
        // still allow caller == address(0) because owner() is a view and should be callable by any address

        // perform the call as the fuzzed caller
        bool ok;
        address returned;
        // Use try/catch to capture if call reverts (should not revert on either ref or mutant)
        try c.owner{gas: gasleft()}() returns (address r) {
            ok = true;
            returned = r;
        } catch {
            ok = false;
            returned = address(0);
        }

        // The single assertion: owner() call must succeed (ok == true) AND the returned owner must be non-zero.
        // This is satisfied by the reference for all callers (deployer set in constructor), but the mutant
        // returns address(0) and will make this assert fail for some inputs (indeed for any caller).
        assertTrue(ok && returned != address(0));
    }
}

