pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // fuzzed caller address; the fuzzer will supply many addresses
    function testFuzz_property(address caller) public {
        // Keep domain wide but exclude address(0) as an external caller to avoid trivial EOA zero address edge
        // (we still allow fuzzer to pick address(0) but we don't want to prune too much)
        // We will call owner() as that caller via low-level call to observe returned value without reverting.

        // Make a low-level call as `caller` to the public owner() view to observe its return value.
        // Use try/catch by invoking via abi.encodeWithSelector to capture returned data.
        bool ok;
        bytes memory ret;

        // Perform call as the fuzzed caller EOA
        vm.prank(caller);
        (ok, ret) = address(c).call(abi.encodeWithSelector(c.owner.selector));

        // If call succeeded, decode owner; otherwise treat as not ok
        address returnedOwner = address(0);
        if (ok && ret.length >= 32) {
            returnedOwner = abi.decode(ret, (address));
        }

        // General rule: for every caller, the reference contract's owner() returns a non-zero address.
        // The mutant returns address(0) instead for some inputs. Assert the returned owner is non-zero.
        assertTrue(returnedOwner != address(0));
    }
}

