pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // fuzzed caller address param; the rule: for any caller address, calling owner() must return a non-zero address
    function testFuzz_property(address caller) public {
        // keep domain wide; no tight restrictions
        // call owner() as the fuzzed caller via low-level call to observe return without changing state
        bool ok;
        // owner() is a view function; we call it via staticcall from the fuzzed caller to emulate any external caller
        bytes memory payload = abi.encodeWithSignature("owner()");
        (bool success, bytes memory returnData) = address(c).call(payload);
        // We don't need to use vm.prank because we only read the return value; different msg.sender doesn't affect owner() return in the correct contract
        // But to match the requirement of fuzzing caller, we also perform the call using the fuzzed caller as msg.sender
        // Use vm.prank to set msg.sender to the fuzzed caller and perform the call, capturing success and return data
        vm.prank(caller);
        try c.owner() returns (address o) {
            ok = (o != address(0));
        } catch {
            ok = false;
        }

        // Single assertion: correct contract always returns non-zero owner for any caller; mutant returning address(0) will fail for some caller inputs
        assertTrue(ok);
    }
}

