pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // fuzz the caller who will invoke transferOwnership
    function testFuzz_property(address caller) public {
        // keep caller non-zero to be a valid EOA for prank; allow zero as well to let fuzzer explore
        // but if caller is zero address, we cannot vm.prank from it; constrain to non-zero
        vm.assume(caller != address(0));

        // Only the owner can call transferOwnership. setUp deployed c with address(this) as owner.
        // We will impersonate the real owner (address(this)) to call transferOwnership and attempt to set new owner to the fuzzed `caller`.
        // The general rule: Reference reverts when newOwner == address(0); mutant does not revert.

        bool ok;
        // perform the call as the owner (the test contract)
        try c.transferOwnership{gas: gasleft()}(caller) {
            ok = true;
        } catch {
            ok = false;
        }

        // The property: for ALL inputs the reference contract will return ok == (caller != address(0)).
        // We observe c.owner() after the call only via its public getter to decide outcome.
        // For the reference (correct) implementation, calling transferOwnership with caller==address(0) should revert -> ok==false,
        // and owner() remains address(this). For non-zero caller, it should succeed -> ok==true and owner()==caller.
        // The test asserts that the call's success flag matches whether the new owner is non-zero by checking owner equality.

        // Compose the observed relation: if ok then owner() == caller else owner() == address(this)
        if (ok) {
            assertTrue(c.owner() == caller);
        } else {
            assertTrue(c.owner() == address(this));
        }
    }
}

