pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this)); }

    // fuzzed param: candidate caller address that will attempt to call transferOwnership
    function testFuzz_property(address caller) public {
        // keep domain wide but avoid zero address for clarity (owner cannot be zero here initially)
        // allow caller == address(0) as admissible too; no strict bound needed

        // determine current owner (deployed C sets owner to deployer i.e., address(this) in constructor of Ownable)
        address currentOwner = c.owner();

        // choose a newOwner to pass to transferOwnership; use caller-derived but ensure non-zero
        // we make newOwner = address(uint160(uint256(keccak256(abi.encodePacked(caller, block.timestamp))))) to be non-deterministic
        address newOwner = address(uint160(uint256(keccak256(abi.encodePacked(caller, block.number, block.timestamp)))));
        if (newOwner == address(0)) {
            newOwner = address(1);
        }

        // attempt transferOwnership as the fuzzed caller and record whether the call succeeded (didn't revert)
        bool ok;
        // impersonate caller
        vm.prank(caller);
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // For the reference contract: only the current owner may successfully call transferOwnership.
        // So ok must equal (caller == currentOwner).
        // This is the single assertion that the correct contract satisfies for ALL inputs, and the mutant
        // (which inverts the check) will cause this to be false for some caller values (e.g., caller != owner succeeds or owner fails).
        assertTrue(ok == (caller == currentOwner));
    }
}
